const revisedAbilities=OFFICIAL_ABILITIES
    .filter(ability=>!DISCARDED_ABILITY_IDS.has(ability.id))
    .map(ability=>{
        const revision=ABILITY_REVISIONS[ability.id]||{};
        const normalized={...ability,...revision,permanentCost:{type:"pd",value:4}};
        normalized.rules={...(ability.rules||{}),...(revision.rules||{}),Custo:"4 PM Permanentes"};
        if(normalized.criticalMargin===0) delete normalized.criticalMargin;
        return normalized;
    });

